/**
 * Truncamento de texto para exibição (títulos, notificações, previews).
 *
 * Todos os comprimentos são medidos em code points Unicode, não em unidades
 * UTF-16: um emoji como '😀' conta 1. (Clusters de grafemas compostos, como
 * bandeiras ou sequências com ZWJ, não recebem tratamento especial.)
 */

/** Número de code points de `s`. */
export function codePointLength(s) {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

/**
 * truncate(text, maxLength, ellipsis = '…')
 *
 * - Se `text` cabe em `maxLength` code points, é devolvido inalterado.
 * - Senão, mantém os primeiros (maxLength - comprimento(ellipsis)) code points,
 *   remove espaços em branco no fim desse trecho e acrescenta `ellipsis`.
 * - Se `maxLength` não comporta nem a reticência mais um caractere
 *   (maxLength <= comprimento(ellipsis)), devolve apenas os primeiros
 *   `maxLength` code points de `text`, sem reticência.
 */
export function truncate(text, maxLength, ellipsis = '…') {
  if (typeof text !== 'string' || typeof ellipsis !== 'string') {
    throw new TypeError('text and ellipsis must be strings');
  }
  if (!Number.isInteger(maxLength) || maxLength < 0) {
    throw new RangeError('maxLength must be a non-negative integer');
  }
  const chars = Array.from(text);
  if (chars.length <= maxLength) return text;

  const ellipsisLength = codePointLength(ellipsis);
  if (maxLength <= ellipsisLength) return chars.slice(0, maxLength).join('');

  const keep = maxLength - ellipsisLength;
  return chars.slice(0, keep).join('').trimEnd() + ellipsis;
}

/**
 * Aplica `truncate` a cada campo string de `record` listado em `limits`, devolvendo um
 * objeto novo (o original não é modificado).
 */
export function truncateFields(record, limits, ellipsis = '…') {
  const out = { ...record };
  for (const [field, max] of Object.entries(limits)) {
    if (typeof out[field] === 'string') out[field] = truncate(out[field], max, ellipsis);
  }
  return out;
}

